import pytest
from ta_attenuator.cells_pool import CellsPool


def test_getting_cell_when_cell_list_is_empty_causes_exception():
    from ta_attenuator.cells_pool import CellsRegistryEmpty
    test_pool = CellsPool()
    with pytest.raises(CellsRegistryEmpty):
        test_pool.get_cell('ENB_1_CELL_1')


def test_releasing_not_used_cell_when_warn_flag_is_off_causes_exception():
    from ta_attenuator.cells_pool import CellsNameNotUnique
    test_pool = CellsPool()
    test_pool.append_used_names('ENB_1_CELL_1')
    number_of_used_cells_before = len(test_pool.used_names)
    with pytest.raises(CellsNameNotUnique):
        test_pool.release_used_names('ENB_1_CELL_2', warn=False)
    assert len(test_pool.used_names) == number_of_used_cells_before


def test_releasing_not_used_cell_when_warn_flag_is_on_does_not_cause_exception():
    test_pool = CellsPool()
    test_pool.append_used_names('ENB_1_CELL_1')
    number_of_used_cells_before = len(test_pool.used_names)
    test_pool.release_used_names('ENB_1_CELL_2', warn=True)
    assert len(test_pool.used_names) == number_of_used_cells_before
